    StringBuilder sb = new StringBuilder();
    String pat = this.pattern; // assume a field named 'pattern' exists
    for (int i = 0; i < pat.length(); i++) {
        char c = pat.charAt(i);
        if (c == '%' && i + 1 < pat.length()) {
            char next = pat.charAt(i + 1);
            switch (next) {
                case 'd':
                    sb.append(new java.text.SimpleDateFormat("yyyy-MM-dd HH:mm:ss.SSS")
                            .format(new java.util.Date(event.getTimeStamp())));
                    i++;
                    break;
                case 'p':
                    sb.append(event.getLevel().toString());
                    i++;
                    break;
                case 'c':
                    sb.append(event.getLoggerName());
                    i++;
                    break;
                case 'm':
                    sb.append(event.getMessage());
                    i++;
                    break;
                case 't':
                    sb.append(event.getThreadName());
                    i++;
                    break;
                case 'n':
                    sb.append(System.lineSeparator());
                    i++;
                    break;
                case '%':
                    sb.append('%');
                    i++;
                    break;
                default:
                    sb.append(c);
                    break;
            }
        } else {
            sb.append(c);
        }
    }
    return sb.toString();
}

